import{_ as r,a0 as a,w as c,s,ao as l,I as i,a1 as n,A as o,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse(`{"title":"在Linux中擴展/縮減LVM（第二部分） | LCTT x X-CMD","titleTemplate":false,"description":"在Linux中擴展/縮減LVM（第二部分） | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux中擴展/縮減LVM（第二部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux中擴展/縮減LVM（第二部分） | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140813 How to Extend or Reduce LVM' s (Logical Volume Management) in Linux--Part II","title":"在Linux中擴展/縮減LVM（第二部分）","tag":"201410","desc":""},"relativePath":"201410/20140813 How to Extend or Reduce LVM' s (Logical Volume Management) in Linux--Part II.md","filePath":"[post].md"}`),d={name:"201410/20140813 How to Extend or Reduce LVM' s (Logical Volume Management) in Linux--Part II.md"};function m(g,e,u,w,L,V){const p=a("Link");return c(),s("div",null,[e[14]||(e[14]=l('<h1 id="在linux中擴展-縮減lvm-第二部分" tabindex="-1">在Linux中擴展/縮減LVM（第二部分） <a class="header-anchor" href="#在linux中擴展-縮減lvm-第二部分" aria-label="Permalink to “在Linux中擴展/縮減LVM（第二部分）”">​</a></h1><p>前面我們已經瞭解了怎樣使用LVM創建彈性的磁盤存儲。這裏，我們將瞭解怎樣來擴展卷組，擴展和縮減邏輯卷。在這裏，我們可以縮減或者擴展邏輯卷管理（LVM）中的分區，LVM也可稱之為彈性卷文件系統。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/LVM_extend.jpg" alt="Extend/Reduce LVMs in Linux"></p><h3 id="前置需求" tabindex="-1">前置需求 <a class="header-anchor" href="#前置需求" aria-label="Permalink to “前置需求”">​</a></h3>',4)),i("ul",null,[i("li",null,[n(p,{href:"http://linux.cn/article-3965-1.html"},{default:o(()=>[...e[0]||(e[0]=[t("使用LVM創建彈性磁盤存儲——第一部分",-1)])]),_:1})])]),e[15]||(e[15]=l(`<h4 id="什麼時候我們需要縮減卷" tabindex="-1">什麼時候我們需要縮減卷？ <a class="header-anchor" href="#什麼時候我們需要縮減卷" aria-label="Permalink to “什麼時候我們需要縮減卷？”">​</a></h4><p>或許我們需要創建一個獨立的分區用於其它用途，或者我們需要擴展任何空間低的分區。遇到這種情況時，使用 LVM我們可以很容易地縮減大尺寸的分區，以及擴展空間低的分區，只要按下面幾個簡易的步驟來即可。</p><h4 id="我的服務器設置-——-需求" tabindex="-1">我的服務器設置 —— 需求 <a class="header-anchor" href="#我的服務器設置-——-需求" aria-label="Permalink to “我的服務器設置 —— 需求”">​</a></h4><ul><li>操作系統 – 安裝有LVM的CentOS 6.5</li><li>服務器IP – 192.168.0.200</li></ul><h3 id="如何擴展卷組以及縮減邏輯卷" tabindex="-1">如何擴展卷組以及縮減邏輯卷 <a class="header-anchor" href="#如何擴展卷組以及縮減邏輯卷" aria-label="Permalink to “如何擴展卷組以及縮減邏輯卷”">​</a></h3><h4 id="邏輯卷擴展" tabindex="-1">邏輯卷擴展 <a class="header-anchor" href="#邏輯卷擴展" aria-label="Permalink to “邏輯卷擴展”">​</a></h4><p>目前，我們已經有一個PV，VG和2個LV。讓我們用下面的命令來列出它們。</p><pre><code># pvs
# vgs
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Logical-Volume-Extending.jpg" alt="Logical Volume Extending"></p><p>邏輯卷擴展</p><p>在物理卷和卷組中沒有空閒空間可用了，所以，現在我們不能擴展邏輯卷的大小。要擴展，我們需要添加一個物理卷（<strong>PV</strong>），然後通過擴展<strong>vg</strong>來擴展卷組，這樣我們就會得到足夠大的空間來擴展邏輯卷大小了。所以，首先我們應該去添加一個物理卷。</p><p>要添加一個新<strong>PV</strong>，我們必須使用fdisk來創建一個LVM分區。</p><pre><code># fdisk -cu /dev/sda
</code></pre><ul><li>選擇<strong>n</strong>來創建新分區。</li><li>選擇<strong>p</strong>來創建主分區。</li><li>選擇我們需要創建的分區號。</li><li>如果有其它可用磁盤，請按<strong>1</strong>。</li><li>使用<strong>t</strong>來修改分區類型。</li><li>輸入<strong>8e</strong>來將分區類型修改為Linux LVM。</li><li>使用<strong>p</strong>來打印創建的分區（這裏我們沒有使用該選項）。</li><li>按<strong>w</strong>寫入修改。</li></ul><p>完成後重啓系統。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-LVM-Partition.jpg" alt="Create LVM Partition"> 創建LVM分區</p><p>使用fdisk列出並檢查我們創建的分區。</p><pre><code># fdisk -l /dev/sda
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-LVM-Partition.jpg" alt="Verify LVM Partition"> 驗證LVM分區</p><p>接下來，使用下列命令來創建新<strong>PV</strong>（物理卷）。</p><pre><code># pvcreate /dev/sda1
</code></pre><p>使用下面的命令來驗證pv。</p><pre><code># pvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-Physical-Volume.jpg" alt="Create Physical Volume"></p><p>創建物理卷</p><h4 id="擴展卷組" tabindex="-1">擴展卷組 <a class="header-anchor" href="#擴展卷組" aria-label="Permalink to “擴展卷組”">​</a></h4><p>添加該pv到<strong>vg_tecmint</strong>卷組來擴展卷組的大小，以獲取更多空間來擴展<strong>lv</strong>。</p><pre><code># vgextend vg_tecmint /dev/sda1
</code></pre><p>讓我們檢查現在正在使用的卷組的大小。</p><pre><code># vgs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Extend-Volume-Group.jpg" alt="Extend Volume Group"></p><p>擴展卷組</p><p>我們甚至可以看到哪個<strong>PV</strong>用於創建使用中的特定卷組。</p><pre><code># pvscan
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Volume-Group.jpg" alt="Check Volume Group"> 檢查卷組</p><p>這裏，我們可以看到卷組所處的物理卷。我們已經添加了一個pv，而且它完全空着。在擴展邏輯卷之前，讓我們先看看我們所擁有的各個卷組的大小。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Each-Logical-Volume.jpg" alt="Check All Logical Volume"></p><p>檢查所有邏輯卷</p><ul><li>LogVol00用於Swap。</li><li>LogVol01用於/。</li><li>現在我們有16.50GB大小的空間用於/（root）。</li><li>當前有4226物理擴展（PE）可用。</li></ul><p>現在，我們打算去擴展/分區<strong>LogVol01</strong>。在擴展後，我們可以像上面那樣列出它的大小以確認。我們能可以使用GB或PE來擴展，這一點我已經在LVM第一部分解釋過了，這裏我使用PE來擴展。</p><p>要獲取可用的物理擴展大小，運行以下命令。</p><pre><code># vgdisplay
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Available-Physical-Extend.jpg" alt="Check Available Physical Size"></p><p>檢查可用的物理擴展</p><p>總共有<strong>4607</strong>空閒PE可用，亦即有<strong>18GB</strong>空間空間可用。因此，我們可以將我們的邏輯卷擴展到<strong>18GB</strong>這麼大。讓我們使用PE大小來擴展。</p><pre><code># lvextend -l +4607 /dev/vg_tecmint/LogVol01
</code></pre><p>使用<strong>+</strong>來添加更多空間。在擴展後，我們需要改變文件系統大小，使用以下命令。</p><pre><code># resize2fs /dev/vg_tecmint/LogVol01
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Expand-Logical-Volume.jpg" alt="Expand Logical Volume"> 擴展邏輯卷</p><ul><li>用來使用物理擴展擴展邏輯卷的命令。</li><li>這裏我們可以看到它從16.51GB擴展到了34GB。</li><li>如果文件系統已被掛載並處於使用中，改變文件系統大小。</li><li>要擴展邏輯卷，我們不需要卸載文件系統</li></ul><p>現在，讓我們看看當前使用的改變大小後的邏輯卷。</p><pre><code># lvdisplay
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Resize-Logical-Volume.jpg" alt="Resize Logical Volume"></p><p>改變邏輯卷大小</p><ul><li>LogVol01用於擴展的卷 /。</li><li>擴展後，從16.50GB上升到了34.50GB。</li><li>C當前擴展，在擴展前有4226，我們已經添加了4607個擴展，因此現在有8833。</li></ul><p>現在，如果我們檢查可用的vg的話，空閒PE將會是0。</p><pre><code># vgdisplay
</code></pre><p>查看擴展的結果。</p><pre><code># pvs
# vgs
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-Resize-Partition.jpg" alt="Verify Resize Partition"></p><p>驗證分區大小改變</p><ul><li>添加的新物理卷。</li><li>卷組vg_tecmint從17.51GB擴展到了35.50GB。</li><li>邏輯卷LogVol01從16.51GB擴展到了34.50GB。</li></ul><p>這裏，我們已經完成擴展卷組和邏輯卷的過程。讓我們一起邁向邏輯卷管理中一些有趣的部分。</p><h4 id="縮減邏輯卷-lvm" tabindex="-1">縮減邏輯卷（LVM） <a class="header-anchor" href="#縮減邏輯卷-lvm" aria-label="Permalink to “縮減邏輯卷（LVM）”">​</a></h4><p>這裏，我們將瞭解如何縮減邏輯卷。人人都説它很危險，在縮減lvm的時候可能會導致災難。縮減lvm在邏輯卷管理中比其它部分要來得確實有趣得多。</p><ul><li>在開始之前，備份好數據總是對的，這樣如果出錯，就不會頭痛了。</li><li>要縮減邏輯卷，需要小心翼翼地完成5個步驟。</li><li>在擴展一個卷的時候，我們可以在該卷掛載時擴展它（在線），但對於縮減，我們必須在縮減前卸載文件系統。</li></ul><p>讓我們來了解一下下面這5個步驟。</p><ul><li>卸載文件系統以便縮減。</li><li>在卸載後檢查文件系統。</li><li>縮減文件系統。</li><li>5減少當前邏輯卷大小。</li><li>再檢查文件系統以防出錯。</li><li>將文件系統再次掛載回去。</li></ul><p>為了演示，我已經創建了獨立的卷組和邏輯卷。這裏，我將縮減邏輯卷<strong>tecmint_reduce_test</strong>。現在它有18GB大小，我們需要將它縮減到<strong>10GB</strong>而不丟失數據。也就是説，我們需要從<strong>18GB</strong>中減少<strong>8GB</strong>。卷中已經有<strong>4GB</strong>被使用。</p><pre><code>18GB ---&gt; 10GB
</code></pre><p>在縮減大小的時候，我們只需要縮減8GB，所以在縮減後它總計會有10GB。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-Logical-Volume.jpg" alt="Reduce Logical Volume"> 縮減邏輯卷</p><p>這裏，我們可以看到文件系統信息。</p><pre><code># df -h
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-File-System-Size.jpg" alt="Check File System Size"> 檢查文件系統大小</p><ul><li>卷大小是18GB。</li><li>它已經使用了3.9GB。</li><li>可用空間是13GB。</li></ul><p>首先，卸載掛載點。</p><pre><code># umount -v /mnt/tecmint_reduce_test/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Unmount-Parition.jpg" alt="Unmount Parition"></p><p>卸載分區</p><p>然後，使用以下命令來檢查文件系統錯誤。</p><pre><code># e2fsck -ff /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Scan-Parition-for-Errors.jpg" alt="Scan Parition for Errors"> 掃描分區錯誤</p><p><strong>注意</strong>：必須通過所有文件系統檢查的5個步驟，若未完全通過，則你的文件系統可能存在問題。</p><p>接下來，縮減文件系統。</p><pre><code># resize2fs /dev/vg_tecmint_extra/tecmint_reduce_test 8GB
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-File-System.jpg" alt="Reduce File System"> 縮減文件系統</p><p>使用GB來縮減邏輯卷。</p><pre><code># lvreduce -L -8G /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-Logical-Volume-Partition.jpg" alt="Reduce Logical Partition"> 縮減邏輯分區</p><p>要使用PE來縮減邏輯卷，我們需要知道默認PE大小和卷組的總PE大小，以進行一次小小的計算來得出準確的縮減大小。</p><pre><code># lvdisplay vg_tecmint_extra
</code></pre><p>這裏，我們需要使用bc命令來做一些小計算來獲得10GB的PE大小。</p><pre><code>1024MB x 10GB = 10240MB or 10GB

10240MB / 4PE = 2048PE
</code></pre><p>按<strong>CTRL+D</strong>來退出BC。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/bc-command.jpg" alt="Calculate PE Size"></p><p>計算PE大小</p><p>使用PE來縮減大小。</p><pre><code># lvreduce -l -2048 /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-Size-Using-PE.jpg" alt="Reduce Size Using PE"> 使用PE來縮減大小</p><p>將文件系統大小調整回去。在這一步中，如果發生任何錯誤，這就意味着我們已經將文件系統搞亂了。</p><pre><code># resize2fs /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Resize-File-System.jpg" alt="Resize File System"></p><p>將文件系統掛載回同樣的掛載點。</p><pre><code># mount /dev/vg_tecmint_extra/tecmint_reduce_test /mnt/tecmint_reduce_test/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Mount-File-System.jpg" alt="Mount File System"> 掛載文件系統</p><p>檢查分區和文件的大小。</p><pre><code># lvdisplay vg_tecmint_extra
</code></pre><p>這裏，我們可以看到最後的結果，邏輯已經被縮減到10GB。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-Logical-Volume-Size.jpg" alt="Verify Logical Volume Size"></p><p>在本文中，我們已經瞭解瞭如何來擴增卷組、邏輯卷以及縮減邏輯卷。在下一部分（第三部分）中，我們將瞭解如何為邏輯卷做快照並將它恢復到更早的狀態。</p><hr>`,113)),i("p",null,[e[2]||(e[2]=t("via: ",-1)),n(p,{href:"http://www.tecmint.com/extend-and-reduce-lvms-in-linux/"},{default:o(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/extend-and-reduce-lvms-in-linux/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=t("作者：",-1)),n(p,{href:"http://www.tecmint.com/author/babinlonston/"},{default:o(()=>[...e[3]||(e[3]=[t("Babin Lonston",-1)])]),_:1}),e[7]||(e[7]=t(" 譯者：",-1)),n(p,{href:"https://github.com/GOLinux"},{default:o(()=>[...e[4]||(e[4]=[t("GOLinux",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:o(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),n(p,{href:"http://linux.cn/"},{default:o(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const v=r(d,[["render",m]]);export{x as __pageData,v as default};
